"""The only place in this system that writes.

A proposal becomes a request only after every one of these has passed, and all of it
is journalled first:

1. the proposal was produced by `planner`, not by a model;
2. it is not a duplicate -- checked against the local journal *and* the server's own
   `GET /_audit`, with the server winning;
3. its mutable precondition has been re-read a moment ago (the seat still exists, the
   room is still there), not at planning time;
4. no earlier write in this case came back `unknown`, which would make later money
   movements unsafe;
5. the intent is committed to disk before the request leaves.

`unknown` is a first-class outcome. A write that timed out is never retried and never
written off as a failure: we go back to `/_audit` and try to settle it, and if we
cannot, we block what depends on it and hand the case over saying so.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable

from .config import Config
from .journal import Journal, canonical_fingerprint
from .ops_client import OpsClient, WriteOutcome, audit_collection_for
from .planner import ActionProposal
from .schemas import ActionState, ActionType, Money, PlannedAction

# The order writes are attempted in. Re-routing first because a later remedy may
# depend on the passenger actually having a journey; escalations last so they can
# describe what did and did not happen.
EXECUTION_ORDER = {
    ActionType.REBOOKING: 0,
    ActionType.HOTEL_VOUCHER: 1,
    ActionType.COMPENSATION_PAYMENT: 2,
    ActionType.REFUND: 3,
    ActionType.GOODWILL_PAYMENT: 4,
    ActionType.ESCALATION: 5,
}

_POST_PATHS = {
    ActionType.REBOOKING: "/rebooking",
    ActionType.HOTEL_VOUCHER: "/vouchers/hotel",
    ActionType.COMPENSATION_PAYMENT: "/payments/compensation",
    ActionType.GOODWILL_PAYMENT: "/payments/goodwill",
    ActionType.REFUND: "/refunds",
    ActionType.ESCALATION: "/escalations",
}

_ID_FIELD = {
    ActionType.REBOOKING: "rebooking_id",
    ActionType.HOTEL_VOUCHER: "voucher_id",
    ActionType.COMPENSATION_PAYMENT: "payment_id",
    ActionType.GOODWILL_PAYMENT: "payment_id",
    ActionType.REFUND: "refund_id",
    ActionType.ESCALATION: "escalation_id",
}


@dataclass
class ExecutionReport:
    actions: list[PlannedAction] = field(default_factory=list)
    errors: list[dict[str, Any]] = field(default_factory=list)
    unknown_outcomes: list[str] = field(default_factory=list)
    escalation_ids: list[str] = field(default_factory=list)
    any_write_succeeded: bool = False


class Executor:
    def __init__(
        self,
        ops: OpsClient,
        journal: Journal,
        config: Config,
        *,
        case_id: str,
        run_id: str,
        dry_run: bool,
    ) -> None:
        self.ops = ops
        self.journal = journal
        self.config = config
        self.case_id = case_id
        self.run_id = run_id
        self.dry_run = dry_run
        self.report = ExecutionReport()
        self._audit_cache: dict[str, Any] | None = None
        self._blocked_by_unknown = False

    # -- audit access ------------------------------------------------------

    def _audit(self, *, refresh: bool = False) -> dict[str, Any]:
        if self._audit_cache is None or refresh:
            try:
                self._audit_cache = self.ops.audit()
            except Exception as exc:  # noqa: BLE001 - recorded, never fatal
                self.report.errors.append(
                    {
                        "stage": "audit_read",
                        "error": str(exc)[:300],
                        "effect": (
                            "Duplicate detection falls back to the local journal "
                            "alone for this case."
                        ),
                    }
                )
                self._audit_cache = {"writes": {}, "totals": {}}
        return self._audit_cache

    # -- duplicate detection ----------------------------------------------

    def _server_equivalents(
        self, proposal: ActionProposal, *, refresh: bool = False
    ) -> list[dict[str, Any]]:
        """Equivalent writes the server itself already holds.

        `GET /_audit` is the authority. If the journal says we did something and the
        server has no record of it, the server was reset and the action has *not*
        happened -- so we do it rather than silently skipping it.
        """
        collection = audit_collection_for(_POST_PATHS[proposal.action_type])
        if not collection:
            return []
        audit = self._audit(refresh=refresh)
        return self.ops.find_matching_writes(
            audit, collection, _matcher_for(proposal)
        )

    # -- precondition refresh ---------------------------------------------

    def _refresh_precondition(
        self, proposal: ActionProposal, inventory: Any
    ) -> tuple[bool, dict[str, Any]]:
        """Re-read the mutable state this write depends on, immediately before it.

        The operations API does not validate `option_id`, seat counts, cabin or fare
        on POST /rebooking (env/ops_server.py), so a 201 is not evidence that a seat
        existed. This check is the only thing standing between a stale option and a
        confirmation the passenger cannot use.
        """
        spec = proposal.refresh
        if not spec:
            return True, {"refreshed": False, "reason": "no mutable precondition"}

        if spec["kind"] == "availability":
            fresh = inventory.own_availability(
                spec["origin"], spec["destination"], spec["date"], proposal.booking_ref or ""
            )
            if fresh.get("unavailable"):
                return False, {
                    "refreshed": False,
                    "reason": "inventory system did not respond on re-check: "
                    + str(fresh.get("error")),
                }
            row = next(
                (
                    r
                    for r in fresh.get("results", [])
                    if r.get("option_id") == spec["option_id"]
                ),
                None,
            )
            if row is None:
                return False, {
                    "refreshed": True,
                    "reason": "the selected option is no longer in inventory",
                    "option_id": spec["option_id"],
                }
            seats = int(row.get("seats_available") or 0)
            if seats < spec["seats_needed"]:
                return False, {
                    "refreshed": True,
                    "reason": "seats fell from planning to execution",
                    "seats_available_now": seats,
                    "seats_needed": spec["seats_needed"],
                }
            if row.get("cabin") != spec["cabin"]:
                return False, {
                    "refreshed": True,
                    "reason": "the option's cabin changed since planning",
                    "cabin_now": row.get("cabin"),
                }
            return True, {
                "refreshed": True,
                "seats_available_now": seats,
                "fare_gbp_now": row.get("fare_gbp"),
                "cabin_now": row.get("cabin"),
            }

        if spec["kind"] == "hotel":
            allocation = inventory.hotel_allocation(spec["station"], spec["night"])
            if allocation is None:
                return False, {
                    "refreshed": True,
                    "reason": "no allocation is held at this station for this night",
                }
            remaining = int(allocation.get("rooms_remaining") or 0)
            if remaining <= 0:
                return False, {
                    "refreshed": True,
                    "reason": "the station allocation was exhausted between planning "
                    "and execution (S4.5)",
                    "rooms_remaining_now": remaining,
                }
            return True, {"refreshed": True, "rooms_remaining_now": remaining}

        return True, {"refreshed": False, "reason": "unrecognised precondition kind"}

    # -- the write path ----------------------------------------------------

    def execute(
        self, proposals: list[ActionProposal], inventory: Any
    ) -> ExecutionReport:
        ordered = sorted(proposals, key=lambda p: EXECUTION_ORDER[p.action_type])
        for proposal in ordered:
            self.report.actions.append(self._execute_one(proposal, inventory))
        self._verify_by_readback()
        return self.report

    def _execute_one(
        self, proposal: ActionProposal, inventory: Any
    ) -> PlannedAction:
        record = _to_record(proposal)

        if proposal.state == ActionState.BLOCKED:
            return record

        fingerprint = canonical_fingerprint(
            ops_base_url=self.config.ops_base_url,
            booking_ref=proposal.booking_ref or "NO-BOOKING",
            action_type=proposal.action_type.value,
            disruption_scope=proposal.disruption_scope,
            params=proposal.fingerprint_params,
        )
        record.fingerprint = fingerprint

        # --- duplicate detection, server first ---------------------------
        prior = self.journal.find_prior_actions(fingerprint)
        server_matches = self._server_equivalents(proposal)
        if server_matches:
            record.state = ActionState.SKIPPED_DUPLICATE
            record.blocked_reason = (
                "An equivalent action already exists in the operations API's own "
                "write log ({}). S15.3 and S16 forbid actioning a remedy twice."
            ).format(
                ", ".join(
                    str(m.get(_ID_FIELD[proposal.action_type], "?"))
                    for m in server_matches[:3]
                )
            )
            record.returned_ids = {
                "existing": [
                    m.get(_ID_FIELD[proposal.action_type]) for m in server_matches[:3]
                ]
            }
            record.verification = "Confirmed against GET /_audit."
            return record
        if prior and not server_matches:
            unknowns = [p for p in prior if p.state == "unknown"]
            if unknowns:
                record.state = ActionState.BLOCKED
                record.blocked_reason = (
                    "A previous attempt at this exact action (journal key {}, case {}) "
                    "ended with an outcome we could not establish, and the server's "
                    "audit log does not show it. Repeating it could double-pay, so it "
                    "is blocked and referred rather than retried."
                ).format(unknowns[0].journal_key, unknowns[0].case_id)
                self.report.unknown_outcomes.append(record.blocked_reason)
                return record
            # Journal says done, server does not have it: the server was reset, so
            # the action has not in fact happened. Proceed, and say why.
            record.preconditions_checked["journal_vs_server"] = (
                "The local journal holds a prior successful {} for this fingerprint "
                "(case {}), but GET /_audit does not show it. The operations service "
                "has been reset since. The server is treated as the authority and the "
                "action is performed."
            ).format(proposal.action_type.value, prior[0].case_id)

        # --- an earlier unknown write in this case makes money unsafe ------
        if self._blocked_by_unknown and proposal.action_type != ActionType.ESCALATION:
            record.state = ActionState.BLOCKED
            record.blocked_reason = (
                "An earlier write in this case ended with an outcome we could not "
                "establish. No further money is moved on this booking until that is "
                "reconciled."
            )
            return record

        # --- refresh the mutable precondition ------------------------------
        ok, refresh_detail = self._refresh_precondition(proposal, inventory)
        record.preconditions_checked["refreshed_immediately_before_write"] = refresh_detail
        if not ok:
            record.state = ActionState.BLOCKED
            record.blocked_reason = (
                "Precondition re-check failed immediately before the write: {}".format(
                    refresh_detail.get("reason")
                )
            )
            return record

        if self.dry_run:
            record.state = ActionState.WOULD_EXECUTE
            record.verification = (
                "Dry run: no request was sent to the operations API. This is a "
                "proposal, not a completed action."
            )
            return record

        # --- commit the intent, then send exactly once ---------------------
        path = _POST_PATHS[proposal.action_type]
        body = dict(proposal.request_body or {})
        journal_key = self.journal.record_intent(
            fingerprint=fingerprint,
            ops_base_url=self.config.ops_base_url,
            case_id=self.case_id,
            run_id=self.run_id,
            action_type=proposal.action_type.value,
            booking_ref=proposal.booking_ref,
            path=path,
            request_body=body,
        )
        record.journal_key = str(journal_key)
        record.state = ActionState.ATTEMPTED
        record.request_summary = _summarise_request(proposal, body)

        outcome = self._post(proposal, body)
        record.response_status = outcome.status

        if outcome.state == "succeeded":
            returned_id = (outcome.body or {}).get(_ID_FIELD[proposal.action_type])
            record.state = ActionState.SUCCEEDED
            record.returned_ids = {
                _ID_FIELD[proposal.action_type]: returned_id,
                **{
                    k: v
                    for k, v in (outcome.body or {}).items()
                    if k in {"status", "rooms_remaining_after", "confirmed_at", "paid_at", "issued_at", "raised_at", "queue"}
                },
            }
            self.journal.update_outcome(
                journal_key,
                state="succeeded",
                response_status=outcome.status,
                returned_id=str(returned_id),
            )
            self.report.any_write_succeeded = True
            if proposal.action_type == ActionType.ESCALATION and returned_id:
                self.report.escalation_ids.append(str(returned_id))
            return record

        if outcome.state == "failed":
            record.state = ActionState.FAILED
            record.error = outcome.error
            self.journal.update_outcome(
                journal_key,
                state="failed",
                response_status=outcome.status,
                error=outcome.error,
            )
            self.report.errors.append(
                {
                    "stage": "write",
                    "action": proposal.action_id,
                    "status": outcome.status,
                    "error": outcome.error,
                    "effect": "The action did not take effect; the case reports it as "
                    "outstanding.",
                }
            )
            return record

        # --- unknown: reconcile, never retry -------------------------------
        self.journal.update_outcome(
            journal_key,
            state="unknown",
            response_status=outcome.status,
            error=outcome.error,
        )
        reconciled = self._reconcile(proposal)
        if reconciled is not None:
            returned_id = reconciled.get(_ID_FIELD[proposal.action_type])
            record.state = ActionState.SUCCEEDED
            record.returned_ids = {_ID_FIELD[proposal.action_type]: returned_id}
            record.verification = (
                "The request's outcome was not returned to us, but GET /_audit shows "
                "the server committed it. Reconciled, not retried."
            )
            self.journal.update_outcome(
                journal_key,
                state="succeeded",
                response_status=outcome.status,
                returned_id=str(returned_id),
                error=outcome.error,
            )
            self.report.any_write_succeeded = True
            if proposal.action_type == ActionType.ESCALATION and returned_id:
                self.report.escalation_ids.append(str(returned_id))
            return record

        record.state = ActionState.UNKNOWN
        record.error = outcome.error
        record.verification = (
            "The outcome could not be established and the server's audit log does not "
            "show the write. It was NOT retried: a blind retry here risks a duplicate "
            "payment or a duplicate journey."
        )
        self._blocked_by_unknown = True
        self.report.unknown_outcomes.append(
            "{} on booking {} has an unknown outcome.".format(
                proposal.action_type.value, proposal.booking_ref
            )
        )
        self.report.errors.append(
            {
                "stage": "write",
                "action": proposal.action_id,
                "status": outcome.status,
                "error": outcome.error,
                "effect": "Outcome unknown. Later money movements on this booking are "
                "blocked and the case is handed to a human.",
            }
        )
        return record

    def _post(self, proposal: ActionProposal, body: dict[str, Any]) -> WriteOutcome:
        sender: Callable[[dict[str, Any]], WriteOutcome] = {
            ActionType.REBOOKING: self.ops.post_rebooking,
            ActionType.HOTEL_VOUCHER: self.ops.post_hotel_voucher,
            ActionType.COMPENSATION_PAYMENT: self.ops.post_compensation,
            ActionType.GOODWILL_PAYMENT: self.ops.post_goodwill,
            ActionType.REFUND: self.ops.post_refund,
            ActionType.ESCALATION: self.ops.post_escalation,
        }[proposal.action_type]
        return sender(body)

    def _reconcile(self, proposal: ActionProposal) -> dict[str, Any] | None:
        """Ask the server whether it committed a write we lost the answer to."""
        matches = self._server_equivalents(proposal, refresh=True)
        return matches[-1] if matches else None

    def _verify_by_readback(self) -> None:
        """Confirm every id we were handed really exists in the server's write log."""
        if self.dry_run:
            return
        succeeded = [
            a for a in self.report.actions if a.state == ActionState.SUCCEEDED
        ]
        if not succeeded:
            return
        audit = self._audit(refresh=True)
        writes = audit.get("writes", {})
        all_ids: set[str] = set()
        for rows in writes.values():
            for row in rows:
                for key in _ID_FIELD.values():
                    if row.get(key):
                        all_ids.add(str(row[key]))
        for action in succeeded:
            returned = (action.returned_ids or {}).get(
                _ID_FIELD[ActionType(action.action_type)]
            )
            if returned and str(returned) in all_ids:
                action.verification = (
                    "Confirmed by readback: {} appears in GET /_audit.".format(returned)
                )
            elif returned:
                action.verification = (
                    "The API returned {} but it does not appear in GET /_audit. "
                    "Confirmation rests on the API response alone.".format(returned)
                )
            else:
                action.verification = (
                    "The API accepted the request but returned no identifier. "
                    "Confirmation rests on the API response alone."
                )


# ---------------------------------------------------------------------------


def _matcher_for(proposal: ActionProposal) -> Callable[[dict[str, Any]], bool]:
    """Equivalence, not equality: same remedy, same passengers, same event."""
    booking = (proposal.booking_ref or "").upper()
    params = proposal.fingerprint_params
    action = proposal.action_type

    def same_booking(write: dict[str, Any]) -> bool:
        return str(write.get("booking_ref", "")).upper() == booking

    def same_passengers(write: dict[str, Any]) -> bool:
        expected = set(params.get("passenger_ids") or [])
        actual = set(write.get("passenger_ids") or [])
        return expected == actual

    if action == ActionType.REBOOKING:
        return lambda w: (
            same_booking(w)
            and w.get("flight_no") == params.get("flight_no")
            and w.get("date") == params.get("date")
            and same_passengers(w)
            and w.get("status") == "CONFIRMED"
        )
    if action == ActionType.HOTEL_VOUCHER:
        return lambda w: (
            same_booking(w)
            and str(w.get("station", "")).upper() == str(params.get("station", "")).upper()
            and w.get("night") == params.get("night")
        )
    if action == ActionType.COMPENSATION_PAYMENT:
        return lambda w: (
            same_booking(w)
            and w.get("type") == "COMPENSATION"
            and _pence(w.get("amount_gbp")) == params.get("amount_minor")
        )
    if action == ActionType.GOODWILL_PAYMENT:
        return lambda w: (
            same_booking(w)
            and w.get("type") == "GOODWILL"
            and _pence(w.get("amount_gbp")) == params.get("amount_minor")
        )
    if action == ActionType.REFUND:
        return lambda w: (
            same_booking(w)
            and _pence(w.get("amount_gbp")) == params.get("amount_minor")
            and same_passengers(w)
        )
    if action == ActionType.ESCALATION:
        return lambda w: (
            same_booking(w)
            and w.get("queue") == params.get("queue")
            and w.get("blocking_clause") == params.get("blocking_clause")
        )
    return lambda w: False


def _pence(value: Any) -> int:
    from decimal import Decimal, ROUND_HALF_UP

    if value is None:
        return -1
    return int(
        (Decimal(str(value)) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    )


def _summarise_request(
    proposal: ActionProposal, body: dict[str, Any]
) -> dict[str, Any]:
    """What was sent, without dragging a whole payload into the record."""
    keep = {
        "booking_ref",
        "passenger_ids",
        "option_id",
        "flight_no",
        "date",
        "cabin",
        "fare_gbp",
        "amount_gbp",
        "station",
        "night",
        "queue",
        "blocking_clause",
    }
    return {
        "path": _POST_PATHS[proposal.action_type],
        "fields": {k: v for k, v in body.items() if k in keep},
    }


def _to_record(proposal: ActionProposal) -> PlannedAction:
    return PlannedAction(
        action_id=proposal.action_id,
        action_type=proposal.action_type,
        state=proposal.state,
        booking_ref=proposal.booking_ref,
        passenger_ids=list(proposal.passenger_ids),
        amount=proposal.amount,
        itinerary=proposal.itinerary,
        policy_basis=list(proposal.policy_basis),
        preconditions_checked=dict(proposal.preconditions),
        consent_basis=proposal.consent_basis,
        blocked_reason=proposal.blocked_reason,
        fingerprint=None,
        journal_key=None,
        request_summary=None,
        response_status=None,
        returned_ids=None,
        verification=None,
        error=None,
    )


def escalation_proposal(
    *,
    action_id: str,
    booking_ref: str | None,
    queue: str,
    summary: str,
    requested_decision: str,
    recommendation: str,
    blocking_clause: str,
    disruption_scope: str,
) -> ActionProposal:
    """Build the typed proposal for POST /escalations (API.md S18)."""
    body = {
        "summary": summary,
        "requested_decision": requested_decision,
        "queue": queue,
        "recommendation": recommendation,
        "blocking_clause": blocking_clause,
    }
    if booking_ref:
        body["booking_ref"] = booking_ref
    return ActionProposal(
        action_id=action_id,
        action_type=ActionType.ESCALATION,
        state=ActionState.PROPOSED,
        booking_ref=booking_ref,
        passenger_ids=[],
        amount=None,
        itinerary=None,
        policy_basis=["S12.5", blocking_clause],
        consent_basis=None,
        preconditions={
            "referral_completeness": (
                "S12.5 requires what the passenger asked for, what the record shows, "
                "the recommended outcome, the blocking condition, and what the "
                "referring party must decide. All five are present."
            )
        },
        request_body=body,
        disruption_scope=disruption_scope,
        fingerprint_params={"queue": queue, "blocking_clause": blocking_clause},
    )


__all__ = [
    "Executor",
    "ExecutionReport",
    "escalation_proposal",
    "Money",
]

input.content:
"""Working one case, end to end.

Ingest -> read the contact (model call 1) -> confirm identity -> gather the
operational facts -> evaluate deterministically -> execute what is authorised ->
refer what is not -> draft the reply (model call 2) -> write the record.

The order matters. Nothing is executed before identity is confirmed, no amount is
chosen outside `policy`/`planner`, and the reply is drafted last, from outcomes that
have already happened.
"""

from __future__ import annotations

import hashlib
import json
import time
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from . import policy
from .config import CASE_TIMEOUT_S, MAX_INBOUND_BYTES, Config
from .executor import Executor, escalation_proposal
from .extract import apply_span_verification, run_extraction
from .identity import resolve_identity
from .journal import Journal
from .llm import BudgetExhausted, LLMClient, ModelCallLimitReached, ModelOutputInvalid
from .narrate import fallback_reply, run_narration
from .ops_client import OpsClient, OpsError, OpsTransportError, AttemptBudgetExhausted
from .planner import (
    CaseFacts,
    HandoverItem,
    Planner,
    live_requests,
)
from .schemas import (
    ActionState,
    ActionType,
    CaseRecord,
    CaseStatus,
    Extraction,
    HumanHandover,
    PlannedAction,
    SourceRef,
    Uncertainty,
)
from .timeutil import UnknownCaseTime, case_now
from .untrusted import detect_injection_indicators, extract_urls

MAX_ESCALATIONS_PER_CASE = 3


class CaseInputError(Exception):
    """The case could not be read or validated."""


@dataclass
class CaseInput:
    case_id: str
    inbound_path: Path
    meta_path: Path | None
    text: str
    meta: dict[str, Any] | None
    sha256: str

    @property
    def meta_from(self) -> str | None:
        return (self.meta or {}).get("from")


def load_case(
    *, inbound: Path, meta: Path | None, case_id: str | None
) -> CaseInput:
    """Read and validate one inbound message and its optional metadata."""
    inbound = Path(inbound)
    if not inbound.is_file():
        raise CaseInputError("No inbound message at {}".format(inbound))
    raw = inbound.read_bytes()
    if not raw.strip():
        raise CaseInputError("Inbound message at {} is empty.".format(inbound))
    if len(raw) > MAX_INBOUND_BYTES:
        raise CaseInputError(
            "Inbound message at {} is {} bytes, above the {} byte limit.".format(
                inbound, len(raw), MAX_INBOUND_BYTES
            )
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CaseInputError(
            "Inbound message at {} is not valid UTF-8: {}".format(inbound, exc)
        ) from exc

    meta_data: dict[str, Any] | None = None
    if meta is not None:
        meta = Path(meta)
        if not meta.is_file():
            raise CaseInputError("No metadata file at {}".format(meta))
        try:
            meta_data = json.loads(meta.read_text(encoding="utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise CaseInputError(
                "Metadata at {} is not readable JSON: {}".format(meta, exc)
            ) from exc
        if not isinstance(meta_data, dict):
            raise CaseInputError(
                "Metadata at {} must be a JSON object, got {}.".format(
                    meta, type(meta_data).__name__
                )
            )

    resolved_id = case_id or (meta_data or {}).get("case_id") or inbound.parent.name
    return CaseInput(
        case_id=str(resolved_id),
        inbound_path=inbound,
        meta_path=meta,
        text=text,
        meta=meta_data,
        sha256=hashlib.sha256(raw).hexdigest(),
    )


def load_case_dir(directory: Path, case_id: str | None = None) -> CaseInput:
    directory = Path(directory)
    meta = directory / "meta.json"
    return load_case(
        inbound=directory / "inbound.txt",
        meta=meta if meta.is_file() else None,
        case_id=case_id,
    )


class InventoryAdapter:
    """The planner's window onto live inventory, with failures made explicit."""

    def __init__(self, ops: OpsClient) -> None:
        self.ops = ops

    def own_availability(
        self, origin: str, destination: str, date_iso: str, booking_ref: str
    ) -> dict[str, Any]:
        try:
            return self.ops.availability(
                origin, destination, date_iso, booking_ref=booking_ref
            )
        except (OpsError, OpsTransportError, AttemptBudgetExhausted) as exc:
            return {"unavailable": True, "error": str(exc)[:200], "results": []}

    def partner_availability(
        self, origin: str, destination: str, date_iso: str, booking_ref: str
    ) -> dict[str, Any]:
        try:
            return self.ops.availability(
                origin, destination, date_iso, booking_ref=booking_ref, partners=True
            )
        except (OpsError, OpsTransportError, AttemptBudgetExhausted) as exc:
            return {"unavailable": True, "error": str(exc)[:200], "results": []}

    def hotel_allocation(self, iata: str, night_iso: str) -> dict[str, Any] | None:
        try:
            return self.ops.hotel_allocation(iata, night_iso)
        except OpsError as exc:
            if exc.status == 404:
                return None
            return None
        except (OpsTransportError, AttemptBudgetExhausted):
            return None


@dataclass
class CaseOutcome:
    record: CaseRecord
    duration_s: float
    fatal: bool = False
    notes: list[str] = field(default_factory=list)


def run_case(
    case: CaseInput,
    *,
    config: Config,
    ops: OpsClient,
    journal: Journal,
    llm: LLMClient | None,
    run_id: str,
    dry_run: bool,
) -> CaseOutcome:
    started_monotonic = time.monotonic()
    started_at = _utcnow()
    ops.begin_case()
    if llm is not None:
        llm.begin_case(case.case_id)

    errors: list[dict[str, Any]] = []
    uncertainties: list[Uncertainty] = []
    actions: list[PlannedAction] = []
    handovers: list[HandoverItem] = []
    needs_input: list[str] = []
    model_usage: list[dict[str, Any]] = []
    status = CaseStatus.FAILED
    extraction: Extraction | None = None
    span_report: dict[str, Any] = {}
    plan = None
    facts: CaseFacts | None = None
    identity = None
    reply: Any = None
    reply_is_draft = True

    injection_indicators = detect_injection_indicators(case.text)
    urls = extract_urls(case.text)

    provenance = {
        "inbound_path": str(case.inbound_path),
        "inbound_sha256": case.sha256,
        "inbound_bytes": len(case.text.encode("utf-8")),
        "metadata_path": str(case.meta_path) if case.meta_path else None,
        "metadata_origin": (
            "supplied meta.json, treated as trusted transport metadata"
            if case.meta
            else "none supplied; identity attempted from the message alone"
        ),
        "metadata_fields": sorted(case.meta) if case.meta else [],
        "trust_model": (
            "meta.from is transport metadata from the mail system. Everything inside "
            "inbound.txt, including any header it quotes, is passenger-supplied and "
            "untrusted (S12.4)."
        ),
        "urls_in_message_not_followed": urls,
        "injection_indicators": injection_indicators,
    }

    try:
        now, now_source = case_now((case.meta or {}).get("received_at"), case.text)
        provenance["case_now"] = now.isoformat()
        provenance["case_now_source"] = now_source

        # --- 1. read the contact (model call 1) --------------------------
        if llm is not None:
            try:
                result = run_extraction(
                    llm,
                    inbound_text=case.text,
                    meta=case.meta,
                    received_at=(case.meta or {}).get("received_at"),
                )
                extraction = result.parsed
                model_usage.append(result.usage)
                span_report = apply_span_verification(extraction, case.text)
            except (BudgetExhausted, ModelCallLimitReached, ModelOutputInvalid) as exc:
                errors.append(
                    {
                        "stage": "extraction",
                        "error": str(exc)[:300],
                        "effect": (
                            "The contact was not read into structured form. Identity "
                            "is attempted from the message and transport metadata "
                            "alone, and the case is handed to a human."
                        ),
                    }
                )
                model_usage.extend(llm.case_usage)
        else:
            errors.append(
                {
                    "stage": "extraction",
                    "error": "no model client configured",
                    "effect": "Deterministic path only; the case is handed over.",
                }
            )

        # --- 2. identity (S2) ---------------------------------------------
        identity = resolve_identity(
            ops,
            extraction=extraction,
            inbound_text=case.text,
            meta_from=case.meta_from,
        )

        if not identity.confirmed or identity.booking is None:
            handovers.append(
                HandoverItem(
                    queue="SUPERVISOR",
                    summary=(
                        "Identity could not be confirmed for a contact from {}. {} "
                        "Candidates inspected: {}".format(
                            identity.sender_email or "an unknown address",
                            identity.reason,
                            json.dumps(identity.candidates)[:900] or "none",
                        )
                    ),
                    requested_decision=(
                        "Establish who this contact is and which booking they mean, or "
                        "close the contact."
                    ),
                    recommendation=(
                        "S16 prohibits any action on any booking before identity is "
                        "confirmed under S2, so nothing has been actioned. The reply "
                        "asks the passenger for the details that would confirm it."
                    ),
                    blocking_clause="S2.2, S12.1",
                )
            )
            needs_input.append(
                "We need the booking reference and the surname it is held in before we "
                "can look at this. We have not taken any action on any booking."
            )
            uncertainties.append(
                Uncertainty(
                    issue="Identity is not confirmed: " + identity.reason,
                    effect_on_decision=(
                        "Every remedy is blocked (S16). The case is referred and the "
                        "passenger is asked for identifying details."
                    ),
                )
            )
        else:
            facts = _gather_facts(ops, identity, extraction, now, now_source, errors)
            planner = Planner(config, InventoryAdapter(ops))
            verified_indexes = set(span_report.get("verified_request_indexes", []))
            requests = (
                live_requests(extraction, verified_indexes) if extraction else []
            )
            if not requests:
                needs_input.append(
                    "We could not establish what you are asking us to do from this "
                    "message. Could you tell us what you would like us to do?"
                )
            plan = planner.plan(
                facts,
                extraction,
                requests=requests,
                injection_indicators=injection_indicators,
            )
            handovers.extend(plan.handovers)
            needs_input.extend(plan.needs_passenger_input)
            uncertainties.extend(
                Uncertainty(issue=u["issue"], effect_on_decision=u["effect_on_decision"])
                for u in plan.uncertainties
            )
            _add_cause_dispute_referral(plan, facts, extraction, handovers)

        # --- 3. execute ----------------------------------------------------
        executor = Executor(
            ops, journal, config, case_id=case.case_id, run_id=run_id, dry_run=dry_run
        )
        proposals = list(plan.proposals) if plan else []
        scope = facts.disruption_scope if facts else "{}:unidentified".format(case.case_id)
        proposals.extend(
            _build_escalations(
                handovers,
                booking_ref=identity.booking_ref if identity else None,
                disruption_scope=scope,
            )
        )
        report = executor.execute(proposals, InventoryAdapter(ops))
        actions = report.actions
        errors.extend(report.errors)
        for unknown in report.unknown_outcomes:
            uncertainties.append(
                Uncertainty(
                    issue=unknown,
                    effect_on_decision=(
                        "Not retried. Dependent writes were blocked and the case is "
                        "handed to a human to settle it against the audit log."
                    ),
                )
            )

        # --- 4. status -----------------------------------------------------
        status = _determine_status(
            actions=actions,
            handovers=handovers,
            needs_input=needs_input,
            identity_confirmed=bool(identity and identity.confirmed),
            dry_run=dry_run,
        )

        # --- 5. draft the reply (model call 2) -----------------------------
        brief = _build_brief(
            case=case,
            identity=identity,
            facts=facts,
            plan=plan,
            actions=actions,
            handovers=handovers,
            needs_input=needs_input,
            extraction=extraction,
            status=status,
            dry_run=dry_run,
        )
        if llm is not None:
            try:
                result = run_narration(llm, brief)
                reply = result.parsed
                model_usage.append(result.usage)
            except (BudgetExhausted, ModelCallLimitReached, ModelOutputInvalid) as exc:
                errors.append(
                    {
                        "stage": "narration",
                        "error": str(exc)[:300],
                        "effect": "The reply was produced from a deterministic template "
                        "instead. The decision and the actions are unaffected.",
                    }
                )
                reply = fallback_reply(brief)
        else:
            reply = fallback_reply(brief)

    except UnknownCaseTime as exc:
        errors.append(
            {
                "stage": "ingest",
                "error": str(exc)[:300],
                "effect": "The case cannot be worked without a reliable date. Handed over.",
            }
        )
        handovers.append(
            HandoverItem(
                queue="GENERAL",
                summary="A contact arrived with no usable date, so nothing "
                "time-relative in it could be resolved.",
                requested_decision="Establish when this was sent and re-run the case.",
                recommendation="Nothing was actioned.",
                blocking_clause="local rule: the host clock is never used as the "
                "incident date",
            )
        )
        status = CaseStatus.FAILED
    except Exception as exc:  # noqa: BLE001 - a case must always leave a record
        errors.append(
            {
                "stage": "case",
                "error": "{}: {}".format(type(exc).__name__, str(exc)[:300]),
                "effect": "The case did not complete. Nothing further was attempted.",
            }
        )
        status = CaseStatus.FAILED

    if reply is None:
        reply = fallback_reply(
            {
                "booking_ref": identity.booking_ref if identity else None,
                "reply_language": extraction.language if extraction else "en",
                "we_need_from_you": needs_input,
                "human_handover": {"required": bool(handovers), "next_steps": []},
            }
        )

    duration = time.monotonic() - started_monotonic
    if duration > CASE_TIMEOUT_S:
        errors.append(
            {
                "stage": "case",
                "error": "case took {:.0f}s, above the {:.0f}s limit".format(
                    duration, CASE_TIMEOUT_S
                ),
                "effect": "Recorded. The work completed, but the limit was exceeded.",
            }
        )

    escalation_ids = [
        str((a.returned_ids or {}).get("escalation_id"))
        for a in actions
        if a.action_type == ActionType.ESCALATION
        and a.state == ActionState.SUCCEEDED
        and (a.returned_ids or {}).get("escalation_id")
    ]
    passenger_facing = [h for h in handovers if not h.internal_only]

    record = CaseRecord(
        case_id=case.case_id,
        run_id=run_id,
        started_at=started_at,
        finished_at=_utcnow(),
        dry_run=dry_run,
        status=status,
        input_provenance=provenance,
        identity_resolution=(
            identity.to_record()
            if identity
            else {"confirmed": False, "reason": "identity resolution did not run"}
        ),
        passenger_requests=_requests_record(extraction, plan, span_report, needs_input),
        verified_facts=_facts_record(facts),
        policy_evaluation=_policy_record(facts, plan),
        decision=_decision_record(plan, actions, status, handovers),
        sources_consulted=list(ops.sources),
        actions=actions,
        uncertainties=uncertainties,
        human_handover=HumanHandover(
            required=bool(passenger_facing),
            reason=(
                "; ".join(h.blocking_clause for h in passenger_facing)
                if passenger_facing
                else None
            ),
            escalation_ids=escalation_ids,
            api_handover_succeeded=bool(escalation_ids),
            next_steps=[h.requested_decision for h in handovers],
        ),
        passenger_response={
            "language": getattr(reply, "language", "en"),
            "subject": getattr(reply, "subject", ""),
            "body": getattr(reply, "body", ""),
            "status": "draft",
            "note": (
                "Draft only. The operations API exposes no send operation, so this "
                "text has not reached the passenger."
            ),
            "generated_by": (
                "model" if llm is not None and not any(
                    e.get("stage") == "narration" for e in errors
                ) else "deterministic template"
            ),
        },
        usage=_usage_record(model_usage, config, journal, run_id, case.case_id),
        errors=errors,
    )
    return CaseOutcome(record=record, duration_s=duration, fatal=status == CaseStatus.FAILED)


# ---------------------------------------------------------------------------
# Fact gathering
# ---------------------------------------------------------------------------


def _gather_facts(
    ops: OpsClient,
    identity: Any,
    extraction: Extraction | None,
    now: Any,
    now_source: str,
    errors: list[dict[str, Any]],
) -> CaseFacts:
    booking = identity.booking
    disruption = booking.get("disruption") or {}
    segment = next(
        (
            s
            for s in booking.get("segments", [])
            if s.get("segment_id") == disruption.get("affected_segment")
        ),
        None,
    )

    flight = None
    if segment:
        try:
            flight = ops.get_flight(segment["flight_no"], segment["date"])
        except (OpsError, OpsTransportError) as exc:
            errors.append(
                {
                    "stage": "facts",
                    "error": str(exc)[:200],
                    "effect": "The flight's operational record could not be read; the "
                    "entitlement service's view of it is used instead.",
                }
            )

    try:
        entitlement = ops.entitlements(booking["booking_ref"])
    except (OpsError, OpsTransportError) as exc:
        entitlement = {
            "status": "SERVICE_ERROR",
            "error": str(exc)[:200],
            "passengers": [],
        }
        errors.append(
            {
                "stage": "facts",
                "error": str(exc)[:200],
                "effect": "The authoritative entitlement figure is unavailable, so no "
                "payment is proposed (S10.3).",
            }
        )

    try:
        customer = ops.customer_history(booking["customer_id"])
    except (OpsError, OpsTransportError) as exc:
        customer = {"customer_id": booking.get("customer_id"), "history": []}
        errors.append(
            {
                "stage": "facts",
                "error": str(exc)[:200],
                "effect": "Case history is unavailable, so previously supplied "
                "benefits cannot be fully checked.",
            }
        )

    advisories: list[dict[str, Any]] = []
    events: list[dict[str, Any]] = []
    if _passenger_disputes_cause(extraction):
        # Only fetched where it earns its attempt: the feed corroborates or
        # contradicts a passenger's account of why the flight went wrong.
        try:
            feed = ops.disruption_feed()
            flight_no = (segment or {}).get("flight_no")
            date_iso = (segment or {}).get("date")
            events = [
                e
                for e in feed.get("flight_events", [])
                if e.get("flight_no") == flight_no and e.get("date") == date_iso
            ]
            stations = {(segment or {}).get("origin"), (segment or {}).get("destination")}
            advisories = [
                a
                for a in feed.get("network_advisories", [])
                if stations & set(a.get("stations", []))
            ]
        except (OpsError, OpsTransportError):
            pass

    cross_check = policy.cross_check_entitlement(entitlement, booking)
    return CaseFacts(
        booking=booking,
        flight=flight,
        entitlement=entitlement,
        customer=customer,
        cross_check=cross_check,
        advisories=advisories,
        flight_events=events,
        now=now,
        now_source=now_source,
    )


_CAUSE_WORDS = {
    "CREW": ("crew", "staff did not", "tripulaci", "personal de cabina"),
    "WEATHER": ("weather", "fog", "storm", "wind", "snow", "niebla", "tormenta"),
    "TECHNICAL": ("technical", "fault", "engineer", "mechanical", "averia", "avería"),
    "ATC_RESTRICTION": ("air traffic", "atc", "slot", "flow restriction"),
    "OPERATIONAL": ("rotation", "late inbound", "commercial decision"),
    "SECURITY": ("security",),
    "GROUND_HANDLING": ("ground handler", "handling agent", "baggage handler"),
}


def _passenger_disputes_cause(extraction: Extraction | None) -> bool:
    if not extraction:
        return False
    return any(c.topic == "cause_of_disruption" for c in extraction.passenger_fact_claims)


def _claimed_cause(extraction: Extraction | None) -> tuple[str | None, str | None]:
    """Map the passenger's account of the cause onto a cause code, if we can."""
    if not extraction:
        return None, None
    for claim in extraction.passenger_fact_claims:
        if claim.topic != "cause_of_disruption":
            continue
        haystack = (claim.claim + " " + claim.quote).casefold()
        for code, words in _CAUSE_WORDS.items():
            if any(word in haystack for word in words):
                return code, claim.quote
    return None, None


def _add_cause_dispute_referral(
    plan: Any, facts: CaseFacts, extraction: Extraction | None, handovers: list[HandoverItem]
) -> None:
    """S3.1: a disputed cause goes to Operations Liaison, and is never amended here."""
    recorded = (facts.flight or {}).get("cause_code") or (
        facts.entitlement.get("journey") or {}
    ).get("cause_code")
    claimed, quote = _claimed_cause(extraction)
    if not recorded or not claimed or claimed == recorded:
        return

    corroboration = "; ".join(
        e.get("detail", "") for e in facts.flight_events[:2]
    ) or "no additional detail in the network operations feed"
    item = HandoverItem(
        queue="OPS_LIAISON",
        summary=(
            "Passenger on booking {} disputes the recorded cause of {}. The "
            "operational record shows {}; the passenger's account points to {}. They "
            "quote: {!r}. Feed detail: {}".format(
                facts.booking_ref,
                (facts.affected_segment or {}).get("flight_no"),
                recorded,
                claimed,
                (quote or "")[:200],
                corroboration[:300],
            )
        ),
        requested_decision="Review the recorded cause and confirm or amend it.",
        recommendation=(
            "S3.1 requires the case to proceed on the operational record and the "
            "discrepancy to be stated plainly to the passenger, which the reply does. "
            "A representative may not amend a cause code (S12.1, S16), so the "
            "entitlement has been assessed on the recorded cause of {}.".format(recorded)
        ),
        blocking_clause="S3.1",
    )
    handovers.append(item)
    plan.handovers.append(item)
    plan.rationale.append(
        "S3.1: the passenger's account of the cause differs from the operational "
        "record. The record governs, the difference is stated in the reply, and the "
        "dispute is referred to Operations Liaison."
    )
    plan.add_uncertainty(
        "The passenger's account of the cause ({}) differs from the recorded cause "
        "({}).".format(claimed, recorded),
        "Assessed on the recorded cause. The dispute is referred; a representative "
        "may not amend a cause code.",
    )


# ---------------------------------------------------------------------------
# Escalations
# ---------------------------------------------------------------------------


def _build_escalations(
    handovers: list[HandoverItem],
    *,
    booking_ref: str | None,
    disruption_scope: str,
) -> list[Any]:
    """One escalation per queue, so routing is preserved without flooding the desk."""
    grouped: dict[str, list[HandoverItem]] = {}
    for item in handovers:
        grouped.setdefault(item.queue, []).append(item)

    proposals = []
    for index, (queue, items) in enumerate(sorted(grouped.items())):
        if index >= MAX_ESCALATIONS_PER_CASE:
            break
        proposals.append(
            escalation_proposal(
                action_id="ACT-esc-{:02d}-{}".format(index + 1, queue.lower()),
                booking_ref=booking_ref,
                queue=queue,
                summary=" || ".join(i.summary for i in items)[:4000],
                requested_decision=" || ".join(i.requested_decision for i in items)[:2000],
                recommendation=" || ".join(i.recommendation for i in items)[:3000],
                blocking_clause="; ".join(
                    sorted({i.blocking_clause for i in items})
                )[:300],
                disruption_scope=disruption_scope,
            )
        )
    return proposals


# ---------------------------------------------------------------------------
# Status
# ---------------------------------------------------------------------------


def _determine_status(
    *,
    actions: list[PlannedAction],
    handovers: list[HandoverItem],
    needs_input: list[str],
    identity_confirmed: bool,
    dry_run: bool,
) -> CaseStatus:
    """Local terminal statuses, decided on what happened to the passenger's requests.

    In a dry run nothing is executed, so `would_execute` stands in for `succeeded`;
    the record still labels every action `would_execute` and never `succeeded`.
    """
    done_states = {ActionState.SUCCEEDED, ActionState.SKIPPED_DUPLICATE}
    if dry_run:
        done_states = done_states | {ActionState.WOULD_EXECUTE}

    passenger_actions = [a for a in actions if a.action_type != ActionType.ESCALATION]
    completed = [a for a in passenger_actions if a.state in done_states]
    outstanding = [
        a
        for a in passenger_actions
        if a.state in {ActionState.BLOCKED, ActionState.FAILED, ActionState.UNKNOWN}
    ]
    passenger_facing_handovers = [h for h in handovers if not h.internal_only]

    if not identity_confirmed:
        return CaseStatus.HANDED_OVER

    if completed:
        if outstanding or passenger_facing_handovers or needs_input:
            return CaseStatus.PARTIALLY_RESOLVED
        return CaseStatus.RESOLVED

    if needs_input and not passenger_facing_handovers:
        return CaseStatus.NEEDS_CLARIFICATION
    if passenger_facing_handovers:
        return CaseStatus.HANDED_OVER
    if outstanding:
        return CaseStatus.PARTIALLY_RESOLVED
    # Nothing to do, and nothing outstanding: the contact was answered outright.
    return CaseStatus.RESOLVED


# ---------------------------------------------------------------------------
# Record assembly
# ---------------------------------------------------------------------------


def _requests_record(
    extraction: Extraction | None,
    plan: Any,
    span_report: dict[str, Any],
    needs_input: list[str],
) -> dict[str, Any]:
    if extraction is None:
        return {
            "read": False,
            "note": "The contact was not read into structured form.",
            "we_asked_the_passenger_for": needs_input,
        }
    prefs = extraction.preferences
    return {
        "read": True,
        "language": extraction.language,
        "requests": plan.requested if plan else [],
        "preferences_and_consent": {
            "explicitly_asked_for_earliest_available": prefs.explicitly_asked_for_earliest_available,
            "arrive_by_local": prefs.arrive_by_local,
            "travel_date_iso": prefs.travel_date_iso,
            "depart_not_before_local": prefs.depart_not_before_local,
            "alternative_origin_airports": prefs.alternative_origin_airports,
            "supporting_quote": prefs.quote,
        },
        "passenger_claims_to_investigate": [
            {"topic": c.topic, "claim": c.claim, "quote": c.quote}
            for c in extraction.passenger_fact_claims
        ],
        "embedded_instructions_refused": [
            {
                "what_it_asks_for": e.what_it_asks_for,
                "claimed_authority": e.claimed_authority,
                "quote": e.quote[:300],
                "treatment": "Refused under S12.4. Recorded, never acted on.",
            }
            for e in extraction.embedded_instructions
        ],
        "unclear_points": extraction.unclear_points,
        "span_verification": span_report,
        "we_asked_the_passenger_for": needs_input,
    }


def _facts_record(facts: CaseFacts | None) -> dict[str, Any]:
    if facts is None:
        return {"gathered": False, "reason": "identity was not confirmed"}
    entitlement = facts.entitlement
    return {
        "gathered": True,
        "case_now": facts.now.isoformat(),
        "case_now_source": facts.now_source,
        "booking": {
            "booking_ref": facts.booking_ref,
            "tier": facts.booking.get("tier"),
            "final_destination": facts.booking.get("final_destination"),
            "total_paid_gbp": facts.booking.get("total_paid_gbp"),
            "fare_breakdown": facts.booking.get("fare_breakdown"),
            "special_requests": facts.booking.get("special_requests"),
            "passengers": [
                {
                    "passenger_id": p.get("passenger_id"),
                    "name": "{} {}".format(p.get("given_name"), p.get("surname")),
                    "passenger_type": p.get("passenger_type"),
                    "assistance": p.get("assistance"),
                    "cabin_booked": p.get("cabin_booked"),
                    "cabin_flown": p.get("cabin_flown"),
                }
                for p in facts.booking.get("passengers", [])
            ],
            "segments": facts.booking.get("segments"),
            "disruption": facts.booking.get("disruption"),
        },
        "flight_operational_record": facts.flight,
        "entitlement_service": {
            "status": entitlement.get("status"),
            "authoritative": entitlement.get("authoritative"),
            "policy_version": entitlement.get("policy_version"),
            "journey": entitlement.get("journey"),
            "compensation": entitlement.get("compensation"),
            "duty_of_care": entitlement.get("duty_of_care"),
            "passengers": entitlement.get("passengers"),
            "total_payable_gbp": entitlement.get("total_payable_gbp"),
        },
        "customer_history": {
            "customer_id": facts.customer.get("customer_id"),
            "tier": facts.customer.get("tier"),
            "flags": facts.customer.get("flags", []),
            "previous_cases": facts.customer.get("history", []),
        },
        "network_feed_corroboration": {
            "flight_events": facts.flight_events,
            "advisories": facts.advisories,
        },
    }


def _policy_record(facts: CaseFacts | None, plan: Any) -> dict[str, Any]:
    if facts is None or plan is None:
        return {"evaluated": False, "reason": "identity was not confirmed"}
    return {
        "evaluated": True,
        "policy_document": "APCP-2026-04 v11.3",
        "authoritative_source": (
            "GET /entitlements/calculate. S10.2 makes its figure the amount owed; "
            "S10.4 forbids substituting a locally derived one."
        ),
        "eligible_remedies": plan.eligible,
        "already_provided": plan.already_provided,
        "independent_cross_check": facts.cross_check.to_record(),
        "rule_references": sorted(
            {clause for p in plan.proposals for clause in p.policy_basis}
        ),
        "answers_given_without_action": plan.answers,
    }


def _decision_record(
    plan: Any, actions: list[PlannedAction], status: CaseStatus, handovers: list[HandoverItem]
) -> dict[str, Any]:
    completed = [
        a
        for a in actions
        if a.state in {ActionState.SUCCEEDED, ActionState.WOULD_EXECUTE}
        and a.action_type != ActionType.ESCALATION
    ]
    return {
        "status": status.value,
        "rationale": plan.rationale if plan else [],
        "what_the_passenger_gets": [
            {
                "action": a.action_type.value,
                "state": a.state.value,
                "amount": str(a.amount) if a.amount else None,
                "passenger_ids": a.passenger_ids,
                "itinerary": a.itinerary,
            }
            for a in completed
        ],
        "rejected_alternatives": plan.rejected_alternatives if plan else [],
        "referred_to_humans": [
            {
                "queue": h.queue,
                "blocking_clause": h.blocking_clause,
                "requested_decision": h.requested_decision,
                "internal_only": h.internal_only,
            }
            for h in handovers
        ],
    }


def _usage_record(
    model_usage: list[dict[str, Any]],
    config: Config,
    journal: Journal,
    run_id: str,
    case_id: str,
) -> dict[str, Any]:
    from decimal import Decimal

    calculated = sum(
        (Decimal(u["calculated_cost_usd"]) for u in model_usage if u.get("calculated_cost_usd")),
        Decimal("0"),
    )
    unresolved = sum(
        (
            Decimal(u["reserved_upper_bound_usd"])
            for u in model_usage
            if not u.get("reservation_resolved")
        ),
        Decimal("0"),
    )
    return {
        "model": config.openai_model,
        "price_source": config.price.source_url,
        "price_verified_on": config.price.verified_on,
        "prices_usd_per_mtok": {
            "input": str(config.price.input_usd_per_mtok),
            "cached_input": str(config.price.cached_input_usd_per_mtok),
            "output": str(config.price.output_usd_per_mtok),
        },
        "calls": model_usage,
        "case_calculated_cost_usd": str(calculated),
        "case_unresolved_reservation_upper_bound_usd": str(unresolved),
        "note": (
            "Cost is derived from the usage the API reported, priced from the table "
            "above. Cached input and reasoning tokens are subsets of input and output "
            "tokens respectively and are each counted once. This is a calculated "
            "figure, not a billing statement from OpenAI."
        ),
    }


def _build_brief(
    *,
    case: CaseInput,
    identity: Any,
    facts: CaseFacts | None,
    plan: Any,
    actions: list[PlannedAction],
    handovers: list[HandoverItem],
    needs_input: list[str],
    extraction: Extraction | None,
    status: CaseStatus,
    dry_run: bool,
) -> dict[str, Any]:
    """Everything the reply may be built from, and nothing else."""
    corrections: list[str] = []
    record_facts: dict[str, Any] = {}
    entitlement_summary: dict[str, Any] = {}

    if facts is not None:
        flight = facts.flight or {}
        journey = facts.entitlement.get("journey") or {}
        record_facts = {
            "flight": flight.get("flight_no") or journey.get("affected_flight"),
            "date": flight.get("date"),
            "status": flight.get("status") or journey.get("flight_status"),
            "cause_code": flight.get("cause_code") or journey.get("cause_code"),
            "cause_note": flight.get("cause_note"),
            "arrival_delay_minutes_at_final_destination": journey.get(
                "arrival_delay_minutes_at_final_destination"
            ),
            "departure_delay_minutes": journey.get("departure_delay_minutes"),
            "distance_km": journey.get("great_circle_distance_km"),
            "band": journey.get("band"),
        }
        claimed, quote = _claimed_cause(extraction)
        recorded = record_facts.get("cause_code")
        if claimed and recorded and claimed != recorded:
            corrections.append(
                "The passenger believes the cause was {}. Our operational record for "
                "{} records the cause as {}: {}. Say this plainly.".format(
                    claimed,
                    record_facts.get("flight"),
                    recorded,
                    (record_facts.get("cause_note") or "")[:200],
                )
            )
        for claim in (extraction.passenger_fact_claims if extraction else []):
            if claim.topic == "delay_length" and journey.get(
                "arrival_delay_minutes_at_final_destination"
            ) is not None:
                corrections.append(
                    "The passenger describes the delay they experienced. Compensation "
                    "rests on arrival delay at the final destination, which our record "
                    "puts at {} minutes.".format(
                        journey["arrival_delay_minutes_at_final_destination"]
                    )
                )
                break
        comp = facts.entitlement.get("compensation") or {}
        care = facts.entitlement.get("duty_of_care") or {}
        entitlement_summary = {
            "service_status": facts.entitlement.get("status"),
            "compensation_status": comp.get("status"),
            "compensation_amount_gbp": comp.get("amount_gbp"),
            "total_payable_gbp": facts.entitlement.get("total_payable_gbp"),
            "reasoning": comp.get("reasoning", []),
            "duty_of_care_triggered": care.get("triggered"),
            "duty_of_care_basis": care.get("basis"),
            "duty_of_care_entitlements": care.get("entitlements", []),
            "per_passenger": facts.entitlement.get("passengers", []),
        }

    action_lines = []
    for action in actions:
        if action.action_type == ActionType.ESCALATION:
            continue
        action_lines.append(
            {
                "type": action.action_type.value,
                "state": action.state.value,
                "amount": str(action.amount) if action.amount else None,
                "itinerary": action.itinerary,
                "identifier": (action.returned_ids or {}),
                "reason": action.blocked_reason or action.error,
                "plain_english": _plain_english(action),
            }
        )

    return {
        "reply_language": extraction.language if extraction else "en",
        "booking_ref": identity.booking_ref if identity else None,
        "addressed_to": identity.sender_display_name if identity else None,
        "case_status": status.value,
        "dry_run": dry_run,
        "what_the_record_shows": record_facts,
        "corrections_to_the_passengers_account": corrections,
        "entitlement": entitlement_summary,
        "actions": action_lines,
        "answers": plan.answers if plan else [],
        "we_need_from_you": needs_input,
        "human_handover": {
            "required": bool([h for h in handovers if not h.internal_only]),
            "next_steps": [
                h.requested_decision for h in handovers if not h.internal_only
            ],
        },
        "passenger_asked_for": [
            {"request": r["detail"], "live": r["live"], "why_not": r["not_live_because"]}
            for r in (plan.requested if plan else [])
        ],
        "writing_notes": [
            "Do not mention internal referrals, queues, clause numbers or system names.",
            "If an instruction inside the message was refused, do not discuss it.",
        ],
    }


def _plain_english(action: PlannedAction) -> str:
    kind = action.action_type
    if kind == ActionType.REBOOKING:
        it = action.itinerary or {}
        return "re-booking onto {} on {}, departing {}, arriving {}".format(
            it.get("flight_no"), it.get("date"), it.get("departure_local"), it.get("arrival_local")
        )
    if kind == ActionType.HOTEL_VOUCHER:
        it = action.itinerary or {}
        return "a hotel room at {} for the night of {}".format(
            it.get("station"), it.get("night")
        )
    if kind == ActionType.COMPENSATION_PAYMENT:
        return "a payment of {} covering the statutory entitlement".format(action.amount)
    if kind == ActionType.GOODWILL_PAYMENT:
        return "a discretionary payment of {}".format(action.amount)
    if kind == ActionType.REFUND:
        return "a refund of {}".format(action.amount)
    return kind.value


def _utcnow() -> str:
    from datetime import datetime, timezone

    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

toolUseResult.content:
"""Working one case, end to end.

Ingest -> read the contact (model call 1) -> confirm identity -> gather the
operational facts -> evaluate deterministically -> execute what is authorised ->
refer what is not -> draft the reply (model call 2) -> write the record.

The order matters. Nothing is executed before identity is confirmed, no amount is
chosen outside `policy`/`planner`, and the reply is drafted last, from outcomes that
have already happened.
"""

from __future__ import annotations

import hashlib
import json
import time
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from . import policy
from .config import CASE_TIMEOUT_S, MAX_INBOUND_BYTES, Config
from .executor import Executor, escalation_proposal
from .extract import apply_span_verification, run_extraction
from .identity import resolve_identity
from .journal import Journal
from .llm import BudgetExhausted, LLMClient, ModelCallLimitReached, ModelOutputInvalid
from .narrate import fallback_reply, run_narration
from .ops_client import OpsClient, OpsError, OpsTransportError, AttemptBudgetExhausted
from .planner import (
    CaseFacts,
    HandoverItem,
    Planner,
    live_requests,
)
from .schemas import (
    ActionState,
    ActionType,
    CaseRecord,
    CaseStatus,
    Extraction,
    HumanHandover,
    PlannedAction,
    SourceRef,
    Uncertainty,
)
from .timeutil import UnknownCaseTime, case_now
from .untrusted import detect_injection_indicators, extract_urls

MAX_ESCALATIONS_PER_CASE = 3


class CaseInputError(Exception):
    """The case could not be read or validated."""


@dataclass
class CaseInput:
    case_id: str
    inbound_path: Path
    meta_path: Path | None
    text: str
    meta: dict[str, Any] | None
    sha256: str

    @property
    def meta_from(self) -> str | None:
        return (self.meta or {}).get("from")


def load_case(
    *, inbound: Path, meta: Path | None, case_id: str | None
) -> CaseInput:
    """Read and validate one inbound message and its optional metadata."""
    inbound = Path(inbound)
    if not inbound.is_file():
        raise CaseInputError("No inbound message at {}".format(inbound))
    raw = inbound.read_bytes()
    if not raw.strip():
        raise CaseInputError("Inbound message at {} is empty.".format(inbound))
    if len(raw) > MAX_INBOUND_BYTES:
        raise CaseInputError(
            "Inbound message at {} is {} bytes, above the {} byte limit.".format(
                inbound, len(raw), MAX_INBOUND_BYTES
            )
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CaseInputError(
            "Inbound message at {} is not valid UTF-8: {}".format(inbound, exc)
        ) from exc

    meta_data: dict[str, Any] | None = None
    if meta is not None:
        meta = Path(meta)
        if not meta.is_file():
            raise CaseInputError("No metadata file at {}".format(meta))
        try:
            meta_data = json.loads(meta.read_text(encoding="utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise CaseInputError(
                "Metadata at {} is not readable JSON: {}".format(meta, exc)
            ) from exc
        if not isinstance(meta_data, dict):
            raise CaseInputError(
                "Metadata at {} must be a JSON object, got {}.".format(
                    meta, type(meta_data).__name__
                )
            )

    resolved_id = case_id or (meta_data or {}).get("case_id") or inbound.parent.name
    return CaseInput(
        case_id=str(resolved_id),
        inbound_path=inbound,
        meta_path=meta,
        text=text,
        meta=meta_data,
        sha256=hashlib.sha256(raw).hexdigest(),
    )


def load_case_dir(directory: Path, case_id: str | None = None) -> CaseInput:
    directory = Path(directory)
    meta = directory / "meta.json"
    return load_case(
        inbound=directory / "inbound.txt",
        meta=meta if meta.is_file() else None,
        case_id=case_id,
    )


class InventoryAdapter:
    """The planner's window onto live inventory, with failures made explicit."""

    def __init__(self, ops: OpsClient) -> None:
        self.ops = ops

    def own_availability(
        self, origin: str, destination: str, date_iso: str, booking_ref: str
    ) -> dict[str, Any]:
        try:
            return self.ops.availability(
                origin, destination, date_iso, booking_ref=booking_ref
            )
        except (OpsError, OpsTransportError, AttemptBudgetExhausted) as exc:
            return {"unavailable": True, "error": str(exc)[:200], "results": []}

    def partner_availability(
        self, origin: str, destination: str, date_iso: str, booking_ref: str
    ) -> dict[str, Any]:
        try:
            return self.ops.availability(
                origin, destination, date_iso, booking_ref=booking_ref, partners=True
            )
        except (OpsError, OpsTransportError, AttemptBudgetExhausted) as exc:
            return {"unavailable": True, "error": str(exc)[:200], "results": []}

    def hotel_allocation(self, iata: str, night_iso: str) -> dict[str, Any] | None:
        try:
            return self.ops.hotel_allocation(iata, night_iso)
        except OpsError as exc:
            if exc.status == 404:
                return None
            return None
        except (OpsTransportError, AttemptBudgetExhausted):
            return None


@dataclass
class CaseOutcome:
    record: CaseRecord
    duration_s: float
    fatal: bool = False
    notes: list[str] = field(default_factory=list)


def run_case(
    case: CaseInput,
    *,
    config: Config,
    ops: OpsClient,
    journal: Journal,
    llm: LLMClient | None,
    run_id: str,
    dry_run: bool,
) -> CaseOutcome:
    started_monotonic = time.monotonic()
    started_at = _utcnow()
    ops.begin_case()
    if llm is not None:
        llm.begin_case(case.case_id)

    errors: list[dict[str, Any]] = []
    uncertainties: list[Uncertainty] = []
    actions: list[PlannedAction] = []
    handovers: list[HandoverItem] = []
    needs_input: list[str] = []
    model_usage: list[dict[str, Any]] = []
    status = CaseStatus.FAILED
    extraction: Extraction | None = None
    span_report: dict[str, Any] = {}
    plan = None
    facts: CaseFacts | None = None
    identity = None
    reply: Any = None
    reply_is_draft = True

    injection_indicators = detect_injection_indicators(case.text)
    urls = extract_urls(case.text)

    provenance = {
        "inbound_path": str(case.inbound_path),
        "inbound_sha256": case.sha256,
        "inbound_bytes": len(case.text.encode("utf-8")),
        "metadata_path": str(case.meta_path) if case.meta_path else None,
        "metadata_origin": (
            "supplied meta.json, treated as trusted transport metadata"
            if case.meta
            else "none supplied; identity attempted from the message alone"
        ),
        "metadata_fields": sorted(case.meta) if case.meta else [],
        "trust_model": (
            "meta.from is transport metadata from the mail system. Everything inside "
            "inbound.txt, including any header it quotes, is passenger-supplied and "
            "untrusted (S12.4)."
        ),
        "urls_in_message_not_followed": urls,
        "injection_indicators": injection_indicators,
    }

    try:
        now, now_source = case_now((case.meta or {}).get("received_at"), case.text)
        provenance["case_now"] = now.isoformat()
        provenance["case_now_source"] = now_source

        # --- 1. read the contact (model call 1) --------------------------
        if llm is not None:
            try:
                result = run_extraction(
                    llm,
                    inbound_text=case.text,
                    meta=case.meta,
                    received_at=(case.meta or {}).get("received_at"),
                )
                extraction = result.parsed
                model_usage.append(result.usage)
                span_report = apply_span_verification(extraction, case.text)
            except (BudgetExhausted, ModelCallLimitReached, ModelOutputInvalid) as exc:
                errors.append(
                    {
                        "stage": "extraction",
                        "error": str(exc)[:300],
                        "effect": (
                            "The contact was not read into structured form. Identity "
                            "is attempted from the message and transport metadata "
                            "alone, and the case is handed to a human."
                        ),
                    }
                )
                model_usage.extend(llm.case_usage)
        else:
            errors.append(
                {
                    "stage": "extraction",
                    "error": "no model client configured",
                    "effect": "Deterministic path only; the case is handed over.",
                }
            )

        # --- 2. identity (S2) ---------------------------------------------
        identity = resolve_identity(
            ops,
            extraction=extraction,
            inbound_text=case.text,
            meta_from=case.meta_from,
        )

        if not identity.confirmed or identity.booking is None:
            handovers.append(
                HandoverItem(
                    queue="SUPERVISOR",
                    summary=(
                        "Identity could not be confirmed for a contact from {}. {} "
                        "Candidates inspected: {}".format(
                            identity.sender_email or "an unknown address",
                            identity.reason,
                            json.dumps(identity.candidates)[:900] or "none",
                        )
                    ),
                    requested_decision=(
                        "Establish who this contact is and which booking they mean, or "
                        "close the contact."
                    ),
                    recommendation=(
                        "S16 prohibits any action on any booking before identity is "
                        "confirmed under S2, so nothing has been actioned. The reply "
                        "asks the passenger for the details that would confirm it."
                    ),
                    blocking_clause="S2.2, S12.1",
                )
            )
            needs_input.append(
                "We need the booking reference and the surname it is held in before we "
                "can look at this. We have not taken any action on any booking."
            )
            uncertainties.append(
                Uncertainty(
                    issue="Identity is not confirmed: " + identity.reason,
                    effect_on_decision=(
                        "Every remedy is blocked (S16). The case is referred and the "
                        "passenger is asked for identifying details."
                    ),
                )
            )
        else:
            facts = _gather_facts(ops, identity, extraction, now, now_source, errors)
            planner = Planner(config, InventoryAdapter(ops))
            verified_indexes = set(span_report.get("verified_request_indexes", []))
            requests = (
                live_requests(extraction, verified_indexes) if extraction else []
            )
            if not requests:
                needs_input.append(
                    "We could not establish what you are asking us to do from this "
                    "message. Could you tell us what you would like us to do?"
                )
            plan = planner.plan(
                facts,
                extraction,
                requests=requests,
                injection_indicators=injection_indicators,
            )
            handovers.extend(plan.handovers)
            needs_input.extend(plan.needs_passenger_input)
            uncertainties.extend(
                Uncertainty(issue=u["issue"], effect_on_decision=u["effect_on_decision"])
                for u in plan.uncertainties
            )
            _add_cause_dispute_referral(plan, facts, extraction, handovers)

        # --- 3. execute ----------------------------------------------------
        executor = Executor(
            ops, journal, config, case_id=case.case_id, run_id=run_id, dry_run=dry_run
        )
        proposals = list(plan.proposals) if plan else []
        scope = facts.disruption_scope if facts else "{}:unidentified".format(case.case_id)
        proposals.extend(
            _build_escalations(
                handovers,
                booking_ref=identity.booking_ref if identity else None,
                disruption_scope=scope,
            )
        )
        report = executor.execute(proposals, InventoryAdapter(ops))
        actions = report.actions
        errors.extend(report.errors)
        for unknown in report.unknown_outcomes:
            uncertainties.append(
                Uncertainty(
                    issue=unknown,
                    effect_on_decision=(
                        "Not retried. Dependent writes were blocked and the case is "
                        "handed to a human to settle it against the audit log."
                    ),
                )
            )

        # --- 4. status -----------------------------------------------------
        status = _determine_status(
            actions=actions,
            handovers=handovers,
            needs_input=needs_input,
            identity_confirmed=bool(identity and identity.confirmed),
            dry_run=dry_run,
        )

        # --- 5. draft the reply (model call 2) -----------------------------
        brief = _build_brief(
            case=case,
            identity=identity,
            facts=facts,
            plan=plan,
            actions=actions,
            handovers=handovers,
            needs_input=needs_input,
            extraction=extraction,
            status=status,
            dry_run=dry_run,
        )
        if llm is not None:
            try:
                result = run_narration(llm, brief)
                reply = result.parsed
                model_usage.append(result.usage)
            except (BudgetExhausted, ModelCallLimitReached, ModelOutputInvalid) as exc:
                errors.append(
                    {
                        "stage": "narration",
                        "error": str(exc)[:300],
                        "effect": "The reply was produced from a deterministic template "
                        "instead. The decision and the actions are unaffected.",
                    }
                )
                reply = fallback_reply(brief)
        else:
            reply = fallback_reply(brief)

    except UnknownCaseTime as exc:
        errors.append(
            {
                "stage": "ingest",
                "error": str(exc)[:300],
                "effect": "The case cannot be worked without a reliable date. Handed over.",
            }
        )
        handovers.append(
            HandoverItem(
                queue="GENERAL",
                summary="A contact arrived with no usable date, so nothing "
                "time-relative in it could be resolved.",
                requested_decision="Establish when this was sent and re-run the case.",
                recommendation="Nothing was actioned.",
                blocking_clause="local rule: the host clock is never used as the "
                "incident date",
            )
        )
        status = CaseStatus.FAILED
    except Exception as exc:  # noqa: BLE001 - a case must always leave a record
        errors.append(
            {
                "stage": "case",
                "error": "{}: {}".format(type(exc).__name__, str(exc)[:300]),
                "effect": "The case did not complete. Nothing further was attempted.",
            }
        )
        status = CaseStatus.FAILED

    if reply is None:
        reply = fallback_reply(
            {
                "booking_ref": identity.booking_ref if identity else None,
                "reply_language": extraction.language if extraction else "en",
                "we_need_from_you": needs_input,
                "human_handover": {"required": bool(handovers), "next_steps": []},
            }
        )

    duration = time.monotonic() - started_monotonic
    if duration > CASE_TIMEOUT_S:
        errors.append(
            {
                "stage": "case",
                "error": "case took {:.0f}s, above the {:.0f}s limit".format(
                    duration, CASE_TIMEOUT_S
                ),
                "effect": "Recorded. The work completed, but the limit was exceeded.",
            }
        )

    escalation_ids = [
        str((a.returned_ids or {}).get("escalation_id"))
        for a in actions
        if a.action_type == ActionType.ESCALATION
        and a.state == ActionState.SUCCEEDED
        and (a.returned_ids or {}).get("escalation_id")
    ]
    passenger_facing = [h for h in handovers if not h.internal_only]

    record = CaseRecord(
        case_id=case.case_id,
        run_id=run_id,
        started_at=started_at,
        finished_at=_utcnow(),
        dry_run=dry_run,
        status=status,
        input_provenance=provenance,
        identity_resolution=(
            identity.to_record()
            if identity
            else {"confirmed": False, "reason": "identity resolution did not run"}
        ),
        passenger_requests=_requests_record(extraction, plan, span_report, needs_input),
        verified_facts=_facts_record(facts),
        policy_evaluation=_policy_record(facts, plan),
        decision=_decision_record(plan, actions, status, handovers),
        sources_consulted=list(ops.sources),
        actions=actions,
        uncertainties=uncertainties,
        human_handover=HumanHandover(
            required=bool(passenger_facing),
            reason=(
                "; ".join(h.blocking_clause for h in passenger_facing)
                if passenger_facing
                else None
            ),
            escalation_ids=escalation_ids,
            api_handover_succeeded=bool(escalation_ids),
            next_steps=[h.requested_decision for h in handovers],
        ),
        passenger_response={
            "language": getattr(reply, "language", "en"),
            "subject": getattr(reply, "subject", ""),
            "body": getattr(reply, "body", ""),
            "status": "draft",
            "note": (
                "Draft only. The operations API exposes no send operation, so this "
                "text has not reached the passenger."
            ),
            "generated_by": (
                "model" if llm is not None and not any(
                    e.get("stage") == "narration" for e in errors
                ) else "deterministic template"
            ),
        },
        usage=_usage_record(model_usage, config, journal, run_id, case.case_id),
        errors=errors,
    )
    return CaseOutcome(record=record, duration_s=duration, fatal=status == CaseStatus.FAILED)


# ---------------------------------------------------------------------------
# Fact gathering
# ---------------------------------------------------------------------------


def _gather_facts(
    ops: OpsClient,
    identity: Any,
    extraction: Extraction | None,
    now: Any,
    now_source: str,
    errors: list[dict[str, Any]],
) -> CaseFacts:
    booking = identity.booking
    disruption = booking.get("disruption") or {}
    segment = next(
        (
            s
            for s in booking.get("segments", [])
            if s.get("segment_id") == disruption.get("affected_segment")
        ),
        None,
    )

    flight = None
    if segment:
        try:
            flight = ops.get_flight(segment["flight_no"], segment["date"])
        except (OpsError, OpsTransportError) as exc:
            errors.append(
                {
                    "stage": "facts",
                    "error": str(exc)[:200],
                    "effect": "The flight's operational record could not be read; the "
                    "entitlement service's view of it is used instead.",
                }
            )

    try:
        entitlement = ops.entitlements(booking["booking_ref"])
    except (OpsError, OpsTransportError) as exc:
        entitlement = {
            "status": "SERVICE_ERROR",
            "error": str(exc)[:200],
            "passengers": [],
        }
        errors.append(
            {
                "stage": "facts",
                "error": str(exc)[:200],
                "effect": "The authoritative entitlement figure is unavailable, so no "
                "payment is proposed (S10.3).",
            }
        )

    try:
        customer = ops.customer_history(booking["customer_id"])
    except (OpsError, OpsTransportError) as exc:
        customer = {"customer_id": booking.get("customer_id"), "history": []}
        errors.append(
            {
                "stage": "facts",
                "error": str(exc)[:200],
                "effect": "Case history is unavailable, so previously supplied "
                "benefits cannot be fully checked.",
            }
        )

    advisories: list[dict[str, Any]] = []
    events: list[dict[str, Any]] = []
    if _passenger_disputes_cause(extraction):
        # Only fetched where it earns its attempt: the feed corroborates or
        # contradicts a passenger's account of why the flight went wrong.
        try:
            feed = ops.disruption_feed()
            flight_no = (segment or {}).get("flight_no")
            date_iso = (segment or {}).get("date")
            events = [
                e
                for e in feed.get("flight_events", [])
                if e.get("flight_no") == flight_no and e.get("date") == date_iso
            ]
            stations = {(segment or {}).get("origin"), (segment or {}).get("destination")}
            advisories = [
                a
                for a in feed.get("network_advisories", [])
                if stations & set(a.get("stations", []))
            ]
        except (OpsError, OpsTransportError):
            pass

    cross_check = policy.cross_check_entitlement(entitlement, booking)
    return CaseFacts(
        booking=booking,
        flight=flight,
        entitlement=entitlement,
        customer=customer,
        cross_check=cross_check,
        advisories=advisories,
        flight_events=events,
        now=now,
        now_source=now_source,
    )


_CAUSE_WORDS = {
    "CREW": ("crew", "staff did not", "tripulaci", "personal de cabina"),
    "WEATHER": ("weather", "fog", "storm", "wind", "snow", "niebla", "tormenta"),
    "TECHNICAL": ("technical", "fault", "engineer", "mechanical", "averia", "avería"),
    "ATC_RESTRICTION": ("air traffic", "atc", "slot", "flow restriction"),
    "OPERATIONAL": ("rotation", "late inbound", "commercial decision"),
    "SECURITY": ("security",),
    "GROUND_HANDLING": ("ground handler", "handling agent", "baggage handler"),
}


def _passenger_disputes_cause(extraction: Extraction | None) -> bool:
    if not extraction:
        return False
    return any(c.topic == "cause_of_disruption" for c in extraction.passenger_fact_claims)


def _claimed_cause(extraction: Extraction | None) -> tuple[str | None, str | None]:
    """Map the passenger's account of the cause onto a cause code, if we can."""
    if not extraction:
        return None, None
    for claim in extraction.passenger_fact_claims:
        if claim.topic != "cause_of_disruption":
            continue
        haystack = (claim.claim + " " + claim.quote).casefold()
        for code, words in _CAUSE_WORDS.items():
            if any(word in haystack for word in words):
                return code, claim.quote
    return None, None


def _add_cause_dispute_referral(
    plan: Any, facts: CaseFacts, extraction: Extraction | None, handovers: list[HandoverItem]
) -> None:
    """S3.1: a disputed cause goes to Operations Liaison, and is never amended here."""
    recorded = (facts.flight or {}).get("cause_code") or (
        facts.entitlement.get("journey") or {}
    ).get("cause_code")
    claimed, quote = _claimed_cause(extraction)
    if not recorded or not claimed or claimed == recorded:
        return

    corroboration = "; ".join(
        e.get("detail", "") for e in facts.flight_events[:2]
    ) or "no additional detail in the network operations feed"
    item = HandoverItem(
        queue="OPS_LIAISON",
        summary=(
            "Passenger on booking {} disputes the recorded cause of {}. The "
            "operational record shows {}; the passenger's account points to {}. They "
            "quote: {!r}. Feed detail: {}".format(
                facts.booking_ref,
                (facts.affected_segment or {}).get("flight_no"),
                recorded,
                claimed,
                (quote or "")[:200],
                corroboration[:300],
            )
        ),
        requested_decision="Review the recorded cause and confirm or amend it.",
        recommendation=(
            "S3.1 requires the case to proceed on the operational record and the "
            "discrepancy to be stated plainly to the passenger, which the reply does. "
            "A representative may not amend a cause code (S12.1, S16), so the "
            "entitlement has been assessed on the recorded cause of {}.".format(recorded)
        ),
        blocking_clause="S3.1",
    )
    handovers.append(item)
    plan.handovers.append(item)
    plan.rationale.append(
        "S3.1: the passenger's account of the cause differs from the operational "
        "record. The record governs, the difference is stated in the reply, and the "
        "dispute is referred to Operations Liaison."
    )
    plan.add_uncertainty(
        "The passenger's account of the cause ({}) differs from the recorded cause "
        "({}).".format(claimed, recorded),
        "Assessed on the recorded cause. The dispute is referred; a representative "
        "may not amend a cause code.",
    )


# ---------------------------------------------------------------------------
# Escalations
# ---------------------------------------------------------------------------


def _build_escalations(
    handovers: list[HandoverItem],
    *,
    booking_ref: str | None,
    disruption_scope: str,
) -> list[Any]:
    """One escalation per queue, so routing is preserved without flooding the desk."""
    grouped: dict[str, list[HandoverItem]] = {}
    for item in handovers:
        grouped.setdefault(item.queue, []).append(item)

    proposals = []
    for index, (queue, items) in enumerate(sorted(grouped.items())):
        if index >= MAX_ESCALATIONS_PER_CASE:
            break
        proposals.append(
            escalation_proposal(
                action_id="ACT-esc-{:02d}-{}".format(index + 1, queue.lower()),
                booking_ref=booking_ref,
                queue=queue,
                summary=" || ".join(i.summary for i in items)[:4000],
                requested_decision=" || ".join(i.requested_decision for i in items)[:2000],
                recommendation=" || ".join(i.recommendation for i in items)[:3000],
                blocking_clause="; ".join(
                    sorted({i.blocking_clause for i in items})
                )[:300],
                disruption_scope=disruption_scope,
            )
        )
    return proposals


# ---------------------------------------------------------------------------
# Status
# ---------------------------------------------------------------------------


def _determine_status(
    *,
    actions: list[PlannedAction],
    handovers: list[HandoverItem],
    needs_input: list[str],
    identity_confirmed: bool,
    dry_run: bool,
) -> CaseStatus:
    """Local terminal statuses, decided on what happened to the passenger's requests.

    In a dry run nothing is executed, so `would_execute` stands in for `succeeded`;
    the record still labels every action `would_execute` and never `succeeded`.
    """
    done_states = {ActionState.SUCCEEDED, ActionState.SKIPPED_DUPLICATE}
    if dry_run:
        done_states = done_states | {ActionState.WOULD_EXECUTE}

    passenger_actions = [a for a in actions if a.action_type != ActionType.ESCALATION]
    completed = [a for a in passenger_actions if a.state in done_states]
    outstanding = [
        a
        for a in passenger_actions
        if a.state in {ActionState.BLOCKED, ActionState.FAILED, ActionState.UNKNOWN}
    ]
    passenger_facing_handovers = [h for h in handovers if not h.internal_only]

    if not identity_confirmed:
        return CaseStatus.HANDED_OVER

    if completed:
        if outstanding or passenger_facing_handovers or needs_input:
            return CaseStatus.PARTIALLY_RESOLVED
        return CaseStatus.RESOLVED

    if needs_input and not passenger_facing_handovers:
        return CaseStatus.NEEDS_CLARIFICATION
    if passenger_facing_handovers:
        return CaseStatus.HANDED_OVER
    if outstanding:
        return CaseStatus.PARTIALLY_RESOLVED
    # Nothing to do, and nothing outstanding: the contact was answered outright.
    return CaseStatus.RESOLVED


# ---------------------------------------------------------------------------
# Record assembly
# ---------------------------------------------------------------------------


def _requests_record(
    extraction: Extraction | None,
    plan: Any,
    span_report: dict[str, Any],
    needs_input: list[str],
) -> dict[str, Any]:
    if extraction is None:
        return {
            "read": False,
            "note": "The contact was not read into structured form.",
            "we_asked_the_passenger_for": needs_input,
        }
    prefs = extraction.preferences
    return {
        "read": True,
        "language": extraction.language,
        "requests": plan.requested if plan else [],
        "preferences_and_consent": {
            "explicitly_asked_for_earliest_available": prefs.explicitly_asked_for_earliest_available,
            "arrive_by_local": prefs.arrive_by_local,
            "travel_date_iso": prefs.travel_date_iso,
            "depart_not_before_local": prefs.depart_not_before_local,
            "alternative_origin_airports": prefs.alternative_origin_airports,
            "supporting_quote": prefs.quote,
        },
        "passenger_claims_to_investigate": [
            {"topic": c.topic, "claim": c.claim, "quote": c.quote}
            for c in extraction.passenger_fact_claims
        ],
        "embedded_instructions_refused": [
            {
                "what_it_asks_for": e.what_it_asks_for,
                "claimed_authority": e.claimed_authority,
                "quote": e.quote[:300],
                "treatment": "Refused under S12.4. Recorded, never acted on.",
            }
            for e in extraction.embedded_instructions
        ],
        "unclear_points": extraction.unclear_points,
        "span_verification": span_report,
        "we_asked_the_passenger_for": needs_input,
    }


def _facts_record(facts: CaseFacts | None) -> dict[str, Any]:
    if facts is None:
        return {"gathered": False, "reason": "identity was not confirmed"}
    entitlement = facts.entitlement
    return {
        "gathered": True,
        "case_now": facts.now.isoformat(),
        "case_now_source": facts.now_source,
        "booking": {
            "booking_ref": facts.booking_ref,
            "tier": facts.booking.get("tier"),
            "final_destination": facts.booking.get("final_destination"),
            "total_paid_gbp": facts.booking.get("total_paid_gbp"),
            "fare_breakdown": facts.booking.get("fare_breakdown"),
            "special_requests": facts.booking.get("special_requests"),
            "passengers": [
                {
                    "passenger_id": p.get("passenger_id"),
                    "name": "{} {}".format(p.get("given_name"), p.get("surname")),
                    "passenger_type": p.get("passenger_type"),
                    "assistance": p.get("assistance"),
                    "cabin_booked": p.get("cabin_booked"),
                    "cabin_flown": p.get("cabin_flown"),
                }
                for p in facts.booking.get("passengers", [])
            ],
            "segments": facts.booking.get("segments"),
            "disruption": facts.booking.get("disruption"),
        },
        "flight_operational_record": facts.flight,
        "entitlement_service": {
            "status": entitlement.get("status"),
            "authoritative": entitlement.get("authoritative"),
            "policy_version": entitlement.get("policy_version"),
            "journey": entitlement.get("journey"),
            "compensation": entitlement.get("compensation"),
            "duty_of_care": entitlement.get("duty_of_care"),
            "passengers": entitlement.get("passengers"),
            "total_payable_gbp": entitlement.get("total_payable_gbp"),
        },
        "customer_history": {
            "customer_id": facts.customer.get("customer_id"),
            "tier": facts.customer.get("tier"),
            "flags": facts.customer.get("flags", []),
            "previous_cases": facts.customer.get("history", []),
        },
        "network_feed_corroboration": {
            "flight_events": facts.flight_events,
            "advisories": facts.advisories,
        },
    }


def _policy_record(facts: CaseFacts | None, plan: Any) -> dict[str, Any]:
    if facts is None or plan is None:
        return {"evaluated": False, "reason": "identity was not confirmed"}
    return {
        "evaluated": True,
        "policy_document": "APCP-2026-04 v11.3",
        "authoritative_source": (
            "GET /entitlements/calculate. S10.2 makes its figure the amount owed; "
            "S10.4 forbids substituting a locally derived one."
        ),
        "eligible_remedies": plan.eligible,
        "already_provided": plan.already_provided,
        "independent_cross_check": facts.cross_check.to_record(),
        "rule_references": sorted(
            {clause for p in plan.proposals for clause in p.policy_basis}
        ),
        "answers_given_without_action": plan.answers,
    }


def _decision_record(
    plan: Any, actions: list[PlannedAction], status: CaseStatus, handovers: list[HandoverItem]
) -> dict[str, Any]:
    completed = [
        a
        for a in actions
        if a.state in {ActionState.SUCCEEDED, ActionState.WOULD_EXECUTE}
        and a.action_type != ActionType.ESCALATION
    ]
    return {
        "status": status.value,
        "rationale": plan.rationale if plan else [],
        "what_the_passenger_gets": [
            {
                "action": a.action_type.value,
                "state": a.state.value,
                "amount": str(a.amount) if a.amount else None,
                "passenger_ids": a.passenger_ids,
                "itinerary": a.itinerary,
            }
            for a in completed
        ],
        "rejected_alternatives": plan.rejected_alternatives if plan else [],
        "referred_to_humans": [
            {
                "queue": h.queue,
                "blocking_clause": h.blocking_clause,
                "requested_decision": h.requested_decision,
                "internal_only": h.internal_only,
            }
            for h in handovers
        ],
    }


def _usage_record(
    model_usage: list[dict[str, Any]],
    config: Config,
    journal: Journal,
    run_id: str,
    case_id: str,
) -> dict[str, Any]:
    from decimal import Decimal

    calculated = sum(
        (Decimal(u["calculated_cost_usd"]) for u in model_usage if u.get("calculated_cost_usd")),
        Decimal("0"),
    )
    unresolved = sum(
        (
            Decimal(u["reserved_upper_bound_usd"])
            for u in model_usage
            if not u.get("reservation_resolved")
        ),
        Decimal("0"),
    )
    return {
        "model": config.openai_model,
        "price_source": config.price.source_url,
        "price_verified_on": config.price.verified_on,
        "prices_usd_per_mtok": {
            "input": str(config.price.input_usd_per_mtok),
            "cached_input": str(config.price.cached_input_usd_per_mtok),
            "output": str(config.price.output_usd_per_mtok),
        },
        "calls": model_usage,
        "case_calculated_cost_usd": str(calculated),
        "case_unresolved_reservation_upper_bound_usd": str(unresolved),
        "note": (
            "Cost is derived from the usage the API reported, priced from the table "
            "above. Cached input and reasoning tokens are subsets of input and output "
            "tokens respectively and are each counted once. This is a calculated "
            "figure, not a billing statement from OpenAI."
        ),
    }


def _build_brief(
    *,
    case: CaseInput,
    identity: Any,
    facts: CaseFacts | None,
    plan: Any,
    actions: list[PlannedAction],
    handovers: list[HandoverItem],
    needs_input: list[str],
    extraction: Extraction | None,
    status: CaseStatus,
    dry_run: bool,
) -> dict[str, Any]:
    """Everything the reply may be built from, and nothing else."""
    corrections: list[str] = []
    record_facts: dict[str, Any] = {}
    entitlement_summary: dict[str, Any] = {}

    if facts is not None:
        flight = facts.flight or {}
        journey = facts.entitlement.get("journey") or {}
        record_facts = {
            "flight": flight.get("flight_no") or journey.get("affected_flight"),
            "date": flight.get("date"),
            "status": flight.get("status") or journey.get("flight_status"),
            "cause_code": flight.get("cause_code") or journey.get("cause_code"),
            "cause_note": flight.get("cause_note"),
            "arrival_delay_minutes_at_final_destination": journey.get(
                "arrival_delay_minutes_at_final_destination"
            ),
            "departure_delay_minutes": journey.get("departure_delay_minutes"),
            "distance_km": journey.get("great_circle_distance_km"),
            "band": journey.get("band"),
        }
        claimed, quote = _claimed_cause(extraction)
        recorded = record_facts.get("cause_code")
        if claimed and recorded and claimed != recorded:
            corrections.append(
                "The passenger believes the cause was {}. Our operational record for "
                "{} records the cause as {}: {}. Say this plainly.".format(
                    claimed,
                    record_facts.get("flight"),
                    recorded,
                    (record_facts.get("cause_note") or "")[:200],
                )
            )
        for claim in (extraction.passenger_fact_claims if extraction else []):
            if claim.topic == "delay_length" and journey.get(
                "arrival_delay_minutes_at_final_destination"
            ) is not None:
                corrections.append(
                    "The passenger describes the delay they experienced. Compensation "
                    "rests on arrival delay at the final destination, which our record "
                    "puts at {} minutes.".format(
                        journey["arrival_delay_minutes_at_final_destination"]
                    )
                )
                break
        comp = facts.entitlement.get("compensation") or {}
        care = facts.entitlement.get("duty_of_care") or {}
        entitlement_summary = {
            "service_status": facts.entitlement.get("status"),
            "compensation_status": comp.get("status"),
            "compensation_amount_gbp": comp.get("amount_gbp"),
            "total_payable_gbp": facts.entitlement.get("total_payable_gbp"),
            "reasoning": comp.get("reasoning", []),
            "duty_of_care_triggered": care.get("triggered"),
            "duty_of_care_basis": care.get("basis"),
            "duty_of_care_entitlements": care.get("entitlements", []),
            "per_passenger": facts.entitlement.get("passengers", []),
        }

    action_lines = []
    for action in actions:
        if action.action_type == ActionType.ESCALATION:
            continue
        action_lines.append(
            {
                "type": action.action_type.value,
                "state": action.state.value,
                "amount": str(action.amount) if action.amount else None,
                "itinerary": action.itinerary,
                "identifier": (action.returned_ids or {}),
                "reason": action.blocked_reason or action.error,
                "plain_english": _plain_english(action),
            }
        )

    return {
        "reply_language": extraction.language if extraction else "en",
        "booking_ref": identity.booking_ref if identity else None,
        "addressed_to": identity.sender_display_name if identity else None,
        "case_status": status.value,
        "dry_run": dry_run,
        "what_the_record_shows": record_facts,
        "corrections_to_the_passengers_account": corrections,
        "entitlement": entitlement_summary,
        "actions": action_lines,
        "answers": plan.answers if plan else [],
        "we_need_from_you": needs_input,
        "human_handover": {
            "required": bool([h for h in handovers if not h.internal_only]),
            "next_steps": [
                h.requested_decision for h in handovers if not h.internal_only
            ],
        },
        "passenger_asked_for": [
            {"request": r["detail"], "live": r["live"], "why_not": r["not_live_because"]}
            for r in (plan.requested if plan else [])
        ],
        "writing_notes": [
            "Do not mention internal referrals, queues, clause numbers or system names.",
            "If an instruction inside the message was refused, do not discuss it.",
        ],
    }


def _plain_english(action: PlannedAction) -> str:
    kind = action.action_type
    if kind == ActionType.REBOOKING:
        it = action.itinerary or {}
        return "re-booking onto {} on {}, departing {}, arriving {}".format(
            it.get("flight_no"), it.get("date"), it.get("departure_local"), it.get("arrival_local")
        )
    if kind == ActionType.HOTEL_VOUCHER:
        it = action.itinerary or {}
        return "a hotel room at {} for the night of {}".format(
            it.get("station"), it.get("night")
        )
    if kind == ActionType.COMPENSATION_PAYMENT:
        return "a payment of {} covering the statutory entitlement".format(action.amount)
    if kind == ActionType.GOODWILL_PAYMENT:
        return "a discretionary payment of {}".format(action.amount)
    if kind == ActionType.REFUND:
        return "a refund of {}".format(action.amount)
    return kind.value


def _utcnow() -> str:
    from datetime import datetime, timezone

    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

input.content:
"""Writing the record out, and summarising a batch.

Case records are written atomically -- rendered to a temporary file in the same
directory and then replaced -- so an interrupted run never leaves a half-written
record that looks parseable.

The batch summary deliberately includes a reconciliation against the operations
API's own `GET /_audit`: every write we claim, and every write the server holds.
A run that exits cleanly is not evidence that the right things happened.
"""

from __future__ import annotations

import json
import os
import tempfile
from collections import Counter
from decimal import Decimal
from pathlib import Path
from typing import Any

from .schemas import ActionState, ActionType, CaseRecord, CaseStatus


def _default(value: Any) -> Any:
    if isinstance(value, Decimal):
        return str(value)
    if isinstance(value, Path):
        return str(value)
    if hasattr(value, "model_dump"):
        return value.model_dump(mode="json")
    if hasattr(value, "isoformat"):
        return value.isoformat()
    return str(value)


def _atomic_write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(payload, indent=2, ensure_ascii=False, default=_default)
    handle = tempfile.NamedTemporaryFile(
        "w", encoding="utf-8", dir=str(path.parent), delete=False, suffix=".tmp"
    )
    try:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
    finally:
        handle.close()
    os.replace(handle.name, path)


def write_case_record(record: CaseRecord, output_dir: Path) -> Path:
    path = Path(output_dir) / "{}.json".format(record.case_id)
    _atomic_write_json(path, record.model_dump(mode="json"))
    return path


def build_batch_summary(
    records: list[CaseRecord],
    *,
    run_id: str,
    dry_run: bool,
    usage_totals: dict[str, Any],
    audit: dict[str, Any] | None,
    config_description: dict[str, Any],
    notes: list[str],
) -> dict[str, Any]:
    statuses = Counter(r.status.value for r in records)
    action_states: Counter[str] = Counter()
    money_minor = 0
    claimed_ids: set[str] = set()

    for record in records:
        for action in record.actions:
            action_states["{}:{}".format(action.action_type.value, action.state.value)] += 1
            if action.state == ActionState.SUCCEEDED and action.amount is not None:
                if action.action_type in {
                    ActionType.COMPENSATION_PAYMENT,
                    ActionType.GOODWILL_PAYMENT,
                    ActionType.REFUND,
                }:
